package org.xwiki.scratch.scratch;

import com.xpn.xwiki.XWikiContext;
import java.util.HashMap;
import java.util.Map;

import jakarta.inject.Inject;
import jakarta.inject.Named;
import jakarta.inject.Provider;
import java.net.URI;
import java.net.URISyntaxException;

import javax.annotation.Priority;

import org.xwiki.component.annotation.Component;
import org.xwiki.component.annotation.InstantiationStrategy;
import org.xwiki.component.descriptor.ComponentInstantiationStrategy;
import org.xwiki.rendering.internal.renderer.xhtml.link.DefaultXHTMLLinkRenderer;
import org.xwiki.rendering.listener.reference.ResourceReference;
import org.xwiki.rendering.listener.reference.ResourceType;

import org.xwiki.script.service.ScriptService;

/**
 * Component that overwrites the default XHTML link renderer to enforce approvals for external links.
 * @version $Id$
 */
@Component
@InstantiationStrategy(ComponentInstantiationStrategy.PER_LOOKUP)
@Priority(900)
public class URLApproverXHTMLLinkRenderer extends DefaultXHTMLLinkRenderer
{
    private static final ResourceReference APPROVAL_REFERENCE
            = new ResourceReference("URLApprover.Code.Approve", ResourceType.DOCUMENT);

    private boolean approved;

    @Inject
    @Named("allowedurls")
    private ScriptService urlApproverScriptService;

    @Inject
    private Provider<XWikiContext> contextProvider;

    private int count = 0;

    @Override
    public void beginLink(ResourceReference reference, boolean freestanding, Map<String, String> parameters)
    {
        approved = isAllowed(reference);
        if (approved) {
            super.beginLink(reference, freestanding, parameters);
        } else {
            super.beginLink(getBlockedReference(reference), freestanding, getBlockedReferenceParameters(reference, parameters));
        }
    }

    @Override
    public void endLink(ResourceReference reference, boolean freestanding, Map<String, String> parameters)
    {
        if (approved) {
            super.endLink(reference, freestanding, parameters);
        } else {
            super.endLink(getBlockedReference(reference), freestanding, getBlockedReferenceParameters(reference, parameters));
        }
    }

    private boolean isAllowed(ResourceReference reference)
    {
        if (!"url".equals(reference.getType().getScheme())) {
            return true;
        }
        String ref = reference.getReference();
        try {
            if (!ref.startsWith("//") && !new URI(ref).isAbsolute()) {
                return true;
            }
        } catch (URISyntaxException e) {
            return false;
        }
        return (/*(URLApproverScriptService)*/ urlApproverScriptService).isAllowed(ref + "/");
    }

    private Map<String, String> getBlockedReferenceParameters(ResourceReference reference, Map<String, String> parameters)
    {
        Map<String, String> p = new HashMap<>(parameters);
        p.put("title", "This URL is not allowed");
        p.put("data-allowedurls-blocked", "1");
        p.put("style", "cursor:not-allowed");
        p.put("data-dbg", String.valueOf(++count))
        return p;
    }

    private ResourceReference getBlockedReference(ResourceReference reference)
    {
        ResourceReference ref = reference.clone();
        ref.setReference("#");
        return ref;
    }
}
